mapper.select:
select distinct psv.id, psv.number, psv.create_time apply_date, psv.visa_reason_id, psv.visa_reason_name, psv.visa_amount, psv.supplier_id, psv.monomer_id, psv.subcontract_order_id, psv.supplier_name, psv.subcontract_class_id, psv.subcontract_class_name, psv.audit_user_id, psv.audit_user_name, psv.audit_status, psv.audit_time, psv.approver_id, psv.approver_name, psv.approve_time, psv.attachment_ids, psv.remark, psv.project_id as 'project.id', cp.name as 'project.name', cp.short_name as 'project.shortName', cp.serial_number as 'project.serialNumber', psv.monomer_id 'monomer.id', m.name 'monomer.name' from project_sub_visa as psv LEFT JOIN contract_project as cp on psv.project_id = cp.id and cp.bool_delete_enum = 0 LEFT JOIN plan_monomer as m on psv.monomer_id = m.id and m.bool_delete_enum = 0 where psv.bool_delete_enum = 0
AND cp.name like concat('%',#{projectName},'%')
AND psv.apply_date >= #{startDate}
AND psv.apply_date <= #{endDate}
AND psv.project_id = #{projectId}
AND psv.supplier_id = #{supplierId}
AND psv.supplier_name like concat('%',#{supplierName},'%')
AND psv.audit_status = #{auditStatus}
AND psv.audit_user_name LIKE concat('%',#{auditUserName},'%')
AND psv.approver_name LIKE concat('%', #{approverName},'%')
ORDER BY psv.audit_status ASC, psv.id DESC
